                path.extension() == Some("rs")
            }
            fn analyze(&self, path: &Utf8Path, source: String) -> Result<Arc<FileAnalysis>> {
                Ok(Arc::new(FileAnalysis {
                    had_parse_errors: false,
                    degradation: None,
                    blocks: vec![block(path, &source, 1, 1)],
                    test_blocks: Vec::new(),
                }))
            }
        }
